-- Shared daily comparisons and server-scored attempts. No client table access.
create table ml_private.daily_catalogue(id text primary key,payload jsonb not null);
create table ml_private.daily_questions(day date not null,no integer not null check(no between 1 and 10),payload jsonb not null,primary key(day,no));
create table ml_private.daily_attempts(day date not null,user_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(name) between 1 and 24),answered integer not null default 0 check(answered between 0 and 10),score integer not null default 0 check(score between 0 and 10),completed_at timestamptz,primary key(day,user_id));
create table ml_private.daily_answers(day date not null,user_id uuid not null,no integer not null,choice text not null check(choice in ('a','b')),correct boolean not null,primary key(day,user_id,no),foreign key(day,user_id) references ml_private.daily_attempts(day,user_id) on delete cascade);
create index daily_attempt_user on ml_private.daily_attempts(user_id);
create index daily_ranking on ml_private.daily_attempts(day,score desc,completed_at,user_id) where completed_at is not null;
alter table ml_private.daily_catalogue enable row level security;
alter table ml_private.daily_questions enable row level security;
alter table ml_private.daily_attempts enable row level security;
alter table ml_private.daily_answers enable row level security;
revoke all on ml_private.daily_catalogue,ml_private.daily_questions,ml_private.daily_attempts,ml_private.daily_answers from public,anon,authenticated;
